<x-app-layout><x-slot name="header"><h2 class="font-semibold text-xl text-gray-800">Students — {{ $subjectOffering->subject->name }}</h2></x-slot><div class="py-8"><div class="max-w-3xl mx-auto sm:px-6 lg:px-8"><div class="bg-white shadow-sm rounded-lg p-6"><div class="mb-5"><p class="text-sm font-medium">{{ $subjectOffering->schoolClass->name }} · {{ $subjectOffering->isClassWide() ? 'All arms' : 'Arm '.$subjectOffering->arm->name }}</p><p class="text-xs text-gray-500">{{ $subjectOffering->term->name }} · {{ $subjectOffering->academicSession->name }}</p></div>@if($eligibleStudents->isEmpty())<p class="text-sm text-gray-500">No active students are eligible.</p>@else<form method="POST" action="{{ route('ict-admin.subject-offerings.registrations.update',$subjectOffering) }}">@csrf @method('PUT')<div class="flex justify-between items-center mb-3"><span class="text-xs text-gray-500">{{ $eligibleStudents->count() }} eligible · <span id="selected_count">0</span> selected</span><span class="text-xs"><button type="button" onclick="setStudents(true)" class="text-brand mr-3">Select all</button><button type="button" onclick="setStudents(false)" class="text-brand">Clear all</button></span></div><div class="max-h-96 overflow-y-auto border rounded-md divide-y">@foreach($eligibleStudents as $student)<label class="flex items-center gap-3 px-4 py-2 text-sm hover:bg-gray-50"><input type="checkbox" name="student_ids[]" value="{{ $student->id }}" class="student-checkbox rounded border-gray-300" @checked(in_array($student->id,$registeredStudentIds))><span>{{ $student->fullName() }}</span><span class="text-gray-400">({{ $student->admission_number }})</span></label>@endforeach</div><div class="flex justify-end gap-3 pt-4"><a href="{{ route('ict-admin.subject-offerings.class',['schoolClass'=>$subjectOffering->class_id,'academic_session_id'=>$subjectOffering->academic_session_id,'term_id'=>$subjectOffering->term_id]) }}" class="px-4 py-2 text-sm text-gray-600">Back</a><x-btn-primary type="s